// "The whole brain" -- 3D soma point cloud of MaleCNS v1.0 with the 16
// on-chain neurons highlighted in the accent gold.
//
// Data: site/data/brain-points.bin (dim cloud, 3x uint16 LE per point) +
// site/data/brain-points.json (honesty manifest: dataset totals, decimation,
// quantization box, and the 16 on-chain neurons with their real positions).
// Both are generated by site/scripts/extract_brain_points.py from the local
// public MaleCNS download -- POSITIONS ONLY. This view is anatomy, not
// wiring; the wiring is what the contract evaluates (the caption says so).
//
// Rendering: vanilla Canvas 2D with a manual perspective projection over
// pre-allocated typed arrays. No dependencies. The render loop only runs
// while the section is on screen (IntersectionObserver) and the tab is
// visible; it pauses otherwise so it can never degrade the live layer.

const BIN_URL = new URL("../data/brain-points.bin", import.meta.url);
const MANIFEST_URL = new URL("../data/brain-points.json", import.meta.url);

const MOBILE_MAX_WIDTH = 700; // matches the CSS breakpoint used elsewhere
const MOBILE_STRIDE = 3; // ~10k of the 30k points on small screens
const AUTO_SPIN = 0.00012; // rad per ms -- slow idle rotation

export class BrainViewer {
  /**
   * @param {HTMLCanvasElement} canvas
   * @param {HTMLElement} captionEl - filled with the honest "shown / total" line
   * @param {HTMLElement} tooltipEl - hidden div for gold-point tooltips
   * @param {object} [opts] {accent}
   */
  constructor(canvas, captionEl, tooltipEl, opts = {}) {
    this.canvas = canvas;
    this.captionEl = captionEl;
    this.tooltipEl = tooltipEl;
    this.accent = opts.accent || "#F0B90B";
    this.ctx = canvas.getContext("2d");
    this.yaw = 0.6;
    this.pitch = -0.25;
    this.dragging = false;
    this.lastPointer = null;
    this.visible = false;
    this.running = false;
    this._raf = 0;
    this._lastT = 0;
    this.points = null; // Float32Array xyz, centered, aspect-true
    this.gold = []; // [{x,y,z,label,bodyId, sx,sy (projected)}]
  }

  async init() {
    let manifest, bin;
    try {
      [manifest, bin] = await Promise.all([
        fetch(MANIFEST_URL).then((r) => {
          if (!r.ok) throw new Error(`manifest HTTP ${r.status}`);
          return r.json();
        }),
        fetch(BIN_URL).then((r) => {
          if (!r.ok) throw new Error(`points HTTP ${r.status}`);
          return r.arrayBuffer();
        }),
      ]);
    } catch (e) {
      // Honest fallback -- never a broken canvas.
      this.canvas.hidden = true;
      if (this.captionEl) {
        this.captionEl.textContent =
          "Brain view unavailable (point data failed to load). The manifest and extraction script are in the repo.";
      }
      return false;
    }

    this.manifest = manifest;
    // Reconstruct true anatomical proportions from the quantization box, then
    // center and scale uniformly (largest span -> 1). Rendering in a naive
    // 0..1 cube would distort the anatomy.
    const min = manifest.quantization.box_min;
    const max = manifest.quantization.box_max;
    const span = [max[0] - min[0] || 1, max[1] - min[1] || 1, max[2] - min[2] || 1];
    const biggest = Math.max(span[0], span[1], span[2]);

    const raw = new Uint16Array(bin);
    const total = Math.floor(raw.length / 3);
    const stride = window.innerWidth <= MOBILE_MAX_WIDTH ? MOBILE_STRIDE : 1;
    const kept = Math.floor((total + stride - 1) / stride);
    const pts = new Float32Array(kept * 3);
    let w = 0;
    for (let i = 0; i < total; i += stride) {
      for (let a = 0; a < 3; a++) {
        const v = raw[i * 3 + a] / 65535;
        pts[w++] = ((v * span[a]) - span[a] / 2) / biggest;
      }
    }
    this.points = pts;
    this.shownCount = kept;
    this._proj = new Float32Array(kept * 3); // sx, sy, depth

    this.gold = (manifest.onchain_neurons || []).map((n) => ({
      x: ((n.pos[0] / 65535) * span[0] - span[0] / 2) / biggest,
      y: ((n.pos[1] / 65535) * span[1] - span[1] / 2) / biggest,
      z: ((n.pos[2] / 65535) * span[2] - span[2] / 2) / biggest,
      label: n.label,
      bodyId: n.bodyId,
      sx: 0,
      sy: 0,
      depth: 0,
    }));

    if (this.captionEl) {
      const shown = kept.toLocaleString("en-US");
      const withSoma = (manifest.neurons_with_soma_position || 0).toLocaleString("en-US");
      const headline = (manifest.dataset_headline_neurons || 166700).toLocaleString("en-US");
      this.captionEl.textContent =
        `Showing ${shown} of the ${withSoma} annotated soma positions in MaleCNS v1.0 ` +
        `(${headline} neurons; decimated for rendering -- see METHODS). ` +
        `Gold = the 16 neurons live on-chain. Positions are anatomy, not wiring -- ` +
        `the wiring is what the contract evaluates. Drag to rotate.`;
    }

    // Read-only stats for verification (e2e asserts these; nothing is
    // injectable through this object).
    window.__nandflyBrainStats = Object.freeze({
      shown: kept,
      highlighted: this.gold.length,
    });

    this._bindInput();
    this._observe();
    this._resize();
    window.addEventListener("resize", () => this._resize());
    return true;
  }

  _observe() {
    const io = new IntersectionObserver(
      (entries) => {
        this.visible = entries.some((e) => e.isIntersecting);
        this._updateRunning();
      },
      { threshold: 0.05 }
    );
    io.observe(this.canvas);
    document.addEventListener("visibilitychange", () => this._updateRunning());
  }

  _updateRunning() {
    const should = this.visible && !document.hidden && !!this.points;
    if (should && !this.running) {
      this.running = true;
      this._lastT = performance.now();
      this._raf = requestAnimationFrame((t) => this._frame(t));
    } else if (!should && this.running) {
      this.running = false;
      cancelAnimationFrame(this._raf);
    }
  }

  _resize() {
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    const rect = this.canvas.getBoundingClientRect();
    const w = Math.max(1, Math.floor(rect.width));
    const h = Math.max(1, Math.floor(rect.height));
    this.canvas.width = Math.floor(w * dpr);
    this.canvas.height = Math.floor(h * dpr);
    this.ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    this.viewW = w;
    this.viewH = h;
    if (!this.running && this.points) this._draw(); // keep a fresh still frame
  }

  _bindInput() {
    const c = this.canvas;
    c.style.touchAction = "pan-y"; // vertical page scroll still works on touch
    c.addEventListener("pointerdown", (e) => {
      this.dragging = true;
      this._dragMoved = false;
      this.lastPointer = { x: e.clientX, y: e.clientY };
      c.setPointerCapture(e.pointerId);
    });
    c.addEventListener("pointermove", (e) => {
      if (!this.dragging || !this.lastPointer) return;
      const dx = e.clientX - this.lastPointer.x;
      const dy = e.clientY - this.lastPointer.y;
      if (Math.abs(dx) + Math.abs(dy) > 3) this._dragMoved = true;
      this.yaw += dx * 0.008;
      this.pitch = Math.max(-1.2, Math.min(1.2, this.pitch + dy * 0.006));
      this.lastPointer = { x: e.clientX, y: e.clientY };
      if (!this.running) this._draw();
    });
    const end = (e) => {
      if (!this.dragging) return;
      this.dragging = false;
      if (!this._dragMoved) this._click(e);
    };
    c.addEventListener("pointerup", end);
    c.addEventListener("pointercancel", () => (this.dragging = false));
  }

  _click(e) {
    const rect = this.canvas.getBoundingClientRect();
    const mx = e.clientX - rect.left;
    const my = e.clientY - rect.top;
    let best = null;
    let bestD = 14 * 14; // 14px hit radius
    for (const g of this.gold) {
      const d = (g.sx - mx) * (g.sx - mx) + (g.sy - my) * (g.sy - my);
      if (d < bestD) {
        bestD = d;
        best = g;
      }
    }
    if (!this.tooltipEl) return;
    if (!best) {
      this.tooltipEl.hidden = true;
      return;
    }
    this.tooltipEl.textContent = `${best.label} -- body #${best.bodyId} -- on-chain`;
    this.tooltipEl.hidden = false;
    this.tooltipEl.style.left = `${Math.round(best.sx)}px`;
    this.tooltipEl.style.top = `${Math.round(best.sy - 14)}px`;
    clearTimeout(this._tooltipTimer);
    this._tooltipTimer = setTimeout(() => (this.tooltipEl.hidden = true), 4000);
  }

  _frame(t) {
    if (!this.running) return;
    const dt = Math.min(100, t - this._lastT);
    this._lastT = t;
    if (!this.dragging) this.yaw += AUTO_SPIN * dt;
    this._draw();
    this._raf = requestAnimationFrame((tt) => this._frame(tt));
  }

  _draw() {
    const ctx = this.ctx;
    const W = this.viewW;
    const H = this.viewH;
    ctx.clearRect(0, 0, W, H);

    const cy = Math.cos(this.yaw);
    const sy = Math.sin(this.yaw);
    const cp = Math.cos(this.pitch);
    const sp = Math.sin(this.pitch);
    const persp = 2.4;
    const scale = Math.min(W, H) * 0.92;
    const cxs = W / 2;
    const cys = H / 2;

    const pts = this.points;
    const n = this.shownCount;
    ctx.fillStyle = "rgba(150, 140, 190, 0.35)";
    for (let i = 0; i < n; i++) {
      const x = pts[i * 3];
      const y = pts[i * 3 + 1];
      const z = pts[i * 3 + 2];
      // yaw around Y, then pitch around X
      const rx = x * cy + z * sy;
      const rz0 = -x * sy + z * cy;
      const ry = y * cp - rz0 * sp;
      const rz = y * sp + rz0 * cp;
      const f = persp / (persp - rz);
      const sxp = cxs + rx * scale * f;
      const syp = cys + ry * scale * f;
      if (sxp < -2 || sxp > W + 2 || syp < -2 || syp > H + 2) continue;
      // depth-shade in two buckets (cheaper than per-point fillStyle churn)
      const sz = rz > 0 ? 1.6 : 1.1;
      ctx.fillRect(sxp, syp, sz, sz);
    }

    // Gold on-chain neurons: drawn last, larger, glowing.
    for (const g of this.gold) {
      const rx = g.x * cy + g.z * sy;
      const rz0 = -g.x * sy + g.z * cy;
      const ry = g.y * cp - rz0 * sp;
      const rz = g.y * sp + rz0 * cp;
      const f = persp / (persp - rz);
      const sxp = cxs + rx * scale * f;
      const syp = cys + ry * scale * f;
      g.sx = sxp;
      g.sy = syp;
      g.depth = rz;
      const r = 2.6 * f + 1.2;
      const glow = ctx.createRadialGradient(sxp, syp, 0, sxp, syp, r * 4);
      glow.addColorStop(0, "rgba(248, 211, 58, 0.5)");
      glow.addColorStop(1, "rgba(248, 211, 58, 0)");
      ctx.fillStyle = glow;
      ctx.beginPath();
      ctx.arc(sxp, syp, r * 4, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = this.accent;
      ctx.beginPath();
      ctx.arc(sxp, syp, r, 0, Math.PI * 2);
      ctx.fill();
    }
  }
}
